/* Enforce hidden attribute behavior */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #1a1a24;
  --meter-metal: #4a5468;
  --meter-metal-dark: #2d3342;
  --meter-metal-light: #718096;
  --screen-bg: #122218;
  --screen-text: #48bb78;
  --screen-border: #0d1710;
  --expired-bg: #c53030;
  --expired-text: #ffffff;
  --btn-bg: #2b3648;
  --btn-border-light: #63b3ed;
  --btn-border-dark: #1a202c;
  --btn-text: #f7fafc;
  --btn-hover: #3b4961;
  --focus-ring: #ecc94b;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--bg-color);
  font-family: 'Courier New', Courier, monospace;
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 20px;
  color: #e2e8f0;
}

.meter-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  max-width: 400px;
}

/* Meter Body Enclosure */
.meter-head {
  position: relative;
  width: 100%;
  background-color: var(--meter-metal);
  border: 6px solid var(--meter-metal-dark);
  box-shadow:
    inset 4px 4px 0 var(--meter-metal-light),
    inset -4px -4px 0 var(--meter-metal-dark),
    0 10px 0 #00000040;
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.meter-cap {
  position: absolute;
  top: -18px;
  width: 140px;
  height: 12px;
  background-color: var(--meter-metal-light);
  border: 4px solid var(--meter-metal-dark);
  border-bottom: none;
}

/* Pixel Display Screen */
.screen-bezel {
  width: 100%;
  background: var(--screen-border);
  padding: 8px;
  border: 4px solid var(--meter-metal-dark);
  box-shadow: inset 2px 2px 0 #00000080;
}

.screen {
  background-color: var(--screen-bg);
  color: var(--screen-text);
  height: 100px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  border: 2px solid #000;
  transition: background-color 0.15s ease, color 0.15s ease;
  user-select: none;
}

.time-text {
  font-size: 2.25rem;
  font-weight: 900;
  letter-spacing: 2px;
  line-height: 1.1;
}

.status-text {
  font-size: 1.5rem;
  font-weight: 900;
  letter-spacing: 3px;
  animation: pixel-pulse 1s steps(2, start) infinite;
}

/* Screen Active & Expired States */
.screen.expired {
  background-color: var(--expired-bg);
  color: var(--expired-text);
}

@keyframes pixel-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.1; }
}

/* Coin Slot Visual Detail */
.coin-slot {
  width: 70px;
  height: 8px;
  background: #111;
  border: 2px solid var(--meter-metal-dark);
  border-radius: 2px;
}

/* Control Keypad */
.controls {
  width: 100%;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.pixel-btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  color: var(--btn-text);
  background-color: var(--btn-bg);
  border: 4px solid var(--meter-metal-dark);
  padding: 14px 10px;
  cursor: pointer;
  box-shadow:
    inset 2px 2px 0 var(--btn-border-light),
    inset -2px -2px 0 var(--btn-border-dark),
    2px 2px 0 #000;
  text-transform: uppercase;
  transition: transform 0.05s ease;
}

.pixel-btn:hover {
  background-color: var(--btn-hover);
}

.pixel-btn:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow:
    inset 2px 2px 0 var(--btn-border-dark),
    inset -2px -2px 0 var(--btn-border-light);
}

.btn-reset {
  grid-column: span 2;
  background-color: #4a2020;
}

.btn-reset:hover {
  background-color: #632a2a;
}

/* Structural Pole and Ground Mount */
.meter-post {
  width: 36px;
  height: 70px;
  background-color: var(--meter-metal-dark);
  border-left: 4px solid var(--meter-metal-light);
  border-right: 4px solid #111;
}

.meter-base {
  width: 100px;
  height: 16px;
  background-color: var(--meter-metal-dark);
  border-top: 4px solid var(--meter-metal-light);
  border-bottom: 4px solid #000;
}

/* Layout adjustments for small screens */
@media (max-width: 360px) {
  .meter-head {
    padding: 16px 12px;
  }

  .time-text {
    font-size: 1.8rem;
  }

  .controls {
    grid-template-columns: 1fr;
  }

  .btn-reset {
    grid-column: span 1;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  let remainingSeconds = 0;
  let timerInterval = null;
  let isRunning = false;

  const screenEl = document.getElementById('meter-screen');
  const timeDisplayEl = document.getElementById('time-display');
  const statusBadgeEl = document.getElementById('status-badge');
  const btnAdd15 = document.getElementById('btn-add-15');
  const btnAdd60 = document.getElementById('btn-add-60');
  const btnReset = document.getElementById('btn-reset');

  function formatTime(totalSeconds) {
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;

    const formattedMinutes = String(minutes).padStart(2, '0');
    const formattedSeconds = String(seconds).padStart(2, '0');

    return `${hours}:${formattedMinutes}:${formattedSeconds}`;
  }

  function updateScreen() {
    if (remainingSeconds <= 0 && isRunning) {
      // Meter expired state
      clearInterval(timerInterval);
      timerInterval = null;
      remainingSeconds = 0;
      isRunning = false;

      screenEl.classList.remove('idle');
      screenEl.classList.add('expired');
      timeDisplayEl.setAttribute('hidden', '');
      statusBadgeEl.removeAttribute('hidden');
    } else if (remainingSeconds > 0) {
      // Active countdown state
      screenEl.classList.remove('expired', 'idle');
      statusBadgeEl.setAttribute('hidden', '');
      timeDisplayEl.removeAttribute('hidden');
      timeDisplayEl.textContent = formatTime(remainingSeconds);
    } else {
      // Reset / Idle state
      screenEl.classList.remove('expired');
      screenEl.classList.add('idle');
      statusBadgeEl.setAttribute('hidden', '');
      timeDisplayEl.removeAttribute('hidden');
      timeDisplayEl.textContent = '0:00:00';
    }
  }

  function startTimer() {
    if (!timerInterval) {
      timerInterval = setInterval(() => {
        if (remainingSeconds > 0) {
          remainingSeconds -= 1;
          updateScreen();
        } else {
          updateScreen();
        }
      }, 1000);
    }
  }

  function addTime(seconds) {
    remainingSeconds += seconds;
    isRunning = true;
    updateScreen();
    startTimer();
  }

  function resetMeter() {
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
    remainingSeconds = 0;
    isRunning = false;
    updateScreen();
  }

  // Wire event listeners
  btnAdd15.addEventListener('click', () => addTime(15 * 60));
  btnAdd60.addEventListener('click', () => addTime(60 * 60));
  btnReset.addEventListener('click', resetMeter);

  // Initialize display
  updateScreen();
});
